window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["28"]={"https://www.gov.uk/foreign-travel-advice/burundi":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"b42b02631762a120776bfb479d8ec7f4f91045814f808002f8dc614158352743","read":"https://www.gov.uk/api/content/foreign-travel-advice/burundi","bytes":57806,"x":"fulltext v1","title":"Burundi travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-01T00:00:00+00:00","mod":"2026-05-21T16:02:33+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Parts of Bujumbura Province"]},{"k":"p","s":["FCDO advises against all travel to Mugina, Cibitoke, Bukinyayana, Bubanza and Mpanda communes due to the risk of the presence of a rebel group in the Kibira National Park and possible armed incursions from the Democratic Republic of the Congo (DRC)."]},{"k":"p","s":["FCDO advises against all travel to parts of Ntahangwa commune, specifically the RN5 road north of Melchior Ndadaye International Airport in Bujumbura towards Cibitoke and west of the Rusizi river towards the border with DRC, including Rusizi National Park (also known as Rusizi Delta Nature Reserve). This is due to possible armed incursions from DRC."]},{"k":"hs","s":["Parts of Butanyerera Province"]},{"k":"p","s":["FCDO advises against all travel on the main RN6 and RN10 roads running west from Kayanza through the Kibira National Park towards Cibitoke, due to the risk of the presence of a rebel group and possible armed incursions from DRC."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/burundi/regional-risks"],"."]},{"k":"h","s":["Burundi-DRC border"]},{"k":"p","s":["Armed group activity and conflict along the border between Burundi and DRC has increased. Be cautious and keep up to date with developments through local media, given heightened insecurity."]},{"k":"p","s":["Armed group activity and the movement of military and refugees in Democratic Republic of Congo (DRC) could affect people on the Burundian side of the border, in Bujumbura Province. The security situation in DRC near to Burundi’s border is unstable (see ",["Democratic Republic of the Congo’s travel advice","https://www.gov.uk/foreign-travel-advice/democratic-republic-of-the-congo"]," for more information)."]},{"k":"p","s":["The only international airport in Burundi is the Melchior Ndadaye International Airport. In the event that flights were not available at the airport, there are currently limited land border options to exit Burundi. The DRC border area is unstable and the Rwandan border is closed. The Tanzania-Burundi border continues to operate normally, although transport options may be limited by the ongoing fuel shortages."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/burundi/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Burundi’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Burundi set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Burundi Embassy in the UK","https://burundiembassy.co.uk/"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Burundi, your passport must have an ‘expiry date’ at least 6 months after the date you arrive and have one blank page. Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Burundi."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["You should ",["apply for a visa online","https://migration.gov.bi/Apply/step1/2"]," ahead of travelling. Visas are issued on arrival in Burundi. A one-month visa costs $90 which can be paid online or in cash on arrival and is valid for single and multiple entries."]},{"k":"p","s":["All travellers without a valid settlement visa or permanent residence must ",["complete the Airport entry visa or Transit visa application","https://migration.gov.bi/Apply/step1/8"]," before arriving in Burundi. Once the application is submitted, you will receive a validation certificate. This certificate will be needed to get your visa upon arrival."]},{"k":"h","s":["Vaccine recommendations"]},{"k":"p","s":["To enter Burundi, you must have a certificate to prove you’ve had a yellow fever vaccination, due to a risk of yellow fever transmission."]},{"k":"p","s":["For more details about health entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Burundi guide","https://travelhealthpro.org.uk/country/38/burundi#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Burundi. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Burundi","https://www.gov.uk/foreign-travel-advice/burundi/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Burundi"]},{"k":"p","s":["Terrorist attacks in Burundi cannot be ruled out."]},{"k":"p","s":["Attacks could be indiscriminate, including in places visited by foreign nationals."]},{"k":"p","s":["Follow the advice of local authorities and exercise caution while travelling around the country."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Armed group activity and conflict along the border between Burundi and DRC has increased. Be cautious and keep up to date with developments through local media, given heightened insecurity. The only international airport in Burundi is the Melchior Ndadaye airport. In the event that flights were not available at the airport, there are currently limited land border options to exit Burundi. The DRC border area is unstable and the Rwandan border is closed. The Tanzania-Burundi border continues to operate normally, although transport options may be limited by the ongoing fuel shortages."]},{"k":"p","s":["Burundi closed its land borders with Rwanda on 11 January 2024 because of escalating bilateral tensions. It is still possible to fly between the two capitals."]},{"k":"p","s":["There are reports of arbitrary arrests, detentions and disappearances of Burundians, most often from civil society, independent media and pockets of society perceived to be anti-government."]},{"k":"p","s":["Grenade attacks are common in Burundi. On 10 May 2024, there were two grenade attacks in central Bujumbura targeting crowded areas. Attacks of this kind can be used by criminal gangs or have a political motivation."]},{"k":"p","s":["Avoid all large gatherings, stay alert and follow the instructions of local authorities."]},{"k":"h","s":["Crime"]},{"k":"p","s":["The crime rate in Burundi is high. There is a risk of muggings at gun and knifepoint, bag-snatching, pickpocketing, burglary, car break-ins and armed carjackings."]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["You can take steps to reduce your personal risk, by:"]},{"k":"li","s":["not walking in the streets or using public transport after dark, even in Bujumbura city centre"]},{"k":"li","s":["not carrying large amounts of money"]},{"k":"li","s":["taking care when withdrawing or exchanging cash, and not doing so at night"]},{"k":"li","s":["staying in hotels that have good security"]},{"k":"li","s":["using hotel safes where possible"]},{"k":"li","s":["keeping copies of important documents, including your passport and visa, separately"]},{"k":"li","s":["being wary of who you plan to meet and where, and informing colleagues or family members of your plans"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Illegal drugs, including cannabis, carry severe penalties."]},{"k":"p","s":["You should expect a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Airports in Burundi have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual acts are illegal. Punishment includes a prison sentence of between 3 months and 2 years and a fine. Burundi is a socially conservative society and LGBT+ people are not accepted. Showing affection in public may receive unwanted and negative attention."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Money"]},{"k":"p","s":["Burundi is largely a cash-based society. Take US dollars dated post-2006. Most businesses will not accept or exchange older currency and US dollars with small tears will also be rejected. You can usually exchange euros and British pounds."]},{"k":"p","s":["There’s a shortage of foreign exchange currencies in Burundi and an unofficial FX exchange rate exists. The unofficial rate can be substantially different from the official exchange rate."]},{"k":"p","s":["Outside Bujumbura credit and debit cards are rarely accepted, and there are not many ATMs. Do not rely on cash withdrawals. You can often use mobile money in tourist hotels."]},{"k":"h","s":["Outdoor activities"]},{"k":"hs","s":["Swimming"]},{"k":"p","s":["Avoid swimming in Lake Tanganyika due to the risk of:"]},{"k":"li","s":["being attacked by wildlife"]},{"k":"li","s":["waterborne diseases"]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Burundi, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Burundi for 6 months. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"],"."]},{"k":"p","s":["Drink -driving is a serious offence in Burundi. Penalties include fines and possibly a prison sentence."]},{"k":"hs","s":["Road conditions"]},{"k":"p","s":["There are only a small number of paved roads and these are sometimes in poor condition. Road infrastructure generally is poor and roads are frequently blocked or damaged by landslides, especially after heavy rain."]},{"k":"p","s":["Landslides can destroy road bridges, making some routes impassable. Check local advice on road conditions when planning travel by road and have an alternative plan in case your route is blocked."]},{"k":"p","s":["Driving standards are very poor and vehicles are often poorly maintained. Serious accidents are common."]},{"k":"p","s":["If you’re involved in a car accident it’s unlikely the emergency services will be able to respond quickly or effectively. You can request help from the Red Cross by calling 109. They will act as first responders, along with the local traffic police (‘police de la protection civile et gestion des catastrophes’). You can contact the police by calling 112."]},{"k":"p","s":["Keep car doors locked and windows closed. Avoid travelling by road outside Bujumbura after dark, because of the security situation and road safety concerns."]},{"k":"hs","s":["Roadblocks"]},{"k":"p","s":["Roadblocks and document checks are common, and not always official. Carry a copy of your passport and visa, but you may need to produce originals."]},{"k":"p","s":["Access into and out of Bujumbura city is controlled by police at night."]},{"k":"hs","s":["Fuel shortages"]},{"k":"p","s":["Burundi is currently suffering from severe fuel shortages. Do not assume you’ll be able to get fuel in the country. Where fuel is available, there can often be long lines."]},{"k":"hs","s":["Public transport"]},{"k":"p","s":["Public transport vehicles (buses and motorbike taxis) are often poorly maintained and have low driving standards."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["The rainy season in Burundi runs from October to May and can result in flash floods. Consular assistance is limited in Burundi."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["Earthquakes in the region can be felt in Burundi. The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Burundi. It only covers regions where FCDO has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/burundi"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/burundi/safety-and-security"],"."]},{"k":"h","s":["Burundi-DRC border"]},{"k":"p","s":["See ",["advice for the Burundi-DRC border on the Warnings and insurance page","https://www.gov.uk/foreign-travel-advice/burundi"],"."]},{"k":"p","s":["In December 2023, rebel militia group Red-Tabara attacked the town of Vugizo, near the DRC border (and 20km from Bujumbura). Local reports suggest up to 20 people died, including one police officer."]},{"k":"p","s":["In September 2023, in Gihanga commune, Bubanza province, Red-Tabara rebels killed two individuals on the RN5 road and reportedly damaged a guidance antenna for Melchior Ndadaye International Airport in Bujumbura."]},{"k":"p","s":["Contact your destination before you set off and make sure you allow enough time to complete your journey during daylight hours."]},{"k":"hs","s":["Former Central Market and bus station located on Chaussee Prince Louis Rwagasore in Bujumbura"]},{"k":"p","s":["Exercise increased caution around the former market and bus station area located on Chaussee Prince Louis Rwagasore in Bujumbura due to the risk of violent crime. On 10 May 2024, a grenade attack took place targeting the bus stop. Consider whether travel in this area of Bujumbura is necessary, avoid all large gatherings and stay alert at all times."]},{"k":"h","s":["Burundi-Rwanda border crossings"]},{"k":"p","s":["Burundi closed its land borders with Rwanda on 11 January 2024 because of escalating tensions."]},{"k":"p","s":["There have previously been armed attacks in the border region with Rwanda. If you’re travelling near the border with Rwanda, check local media for the latest developments and stay up to date with this travel advice page."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 112 and ask for an ambulance."]},{"k":"p","s":["You can also request help from the Red Cross by calling 109."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Burundi","https://travelhealthpro.org.uk/country/38/burundi#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Burundi","https://travelhealthpro.org.uk/country/38/burundi"],", including:"]},{"k":"li","s":["Zika"]},{"k":"li","s":["malaria and dengue"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["mpox"]},{"k":"p","s":["Altitude sickness is a risk in parts of Burundi. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"hs","s":["Ebola"]},{"k":"p","s":["On 15 May the Democratic Republic of Congo Ministry of Health announced an outbreak of Ebola Bundibugyo in the North-Eastern Ituri Province. Read more about the ",["Ebola outbreak on TravelHealth Pro","https://travelhealthpro.org.uk/country/63/democratic-republic-of-the-congo#Outbreaks"]," and see ",["information on Ebola and similar diseases.","https://travelhealthpro.org.uk/factsheet/68/viral-haemorrhagic-fever"]," World Health Organisation (WHO) have ",["declared this a Public Health Emergency of International Concern","https://www.who.int/news/item/17-05-2026-epidemic-of-ebola-disease-in-the-democratic-republic-of-the-congo-and-uganda-determined-a-public-health-emergency-of-international-concern"],"."]},{"k":"p","s":["Due to the outbreak, you may experience heightened health screening at international borders in the region. ",["Check entry requirements","https://www.gov.uk/foreign-travel-advice/"]," for the country you’re travelling to or transiting."]},{"k":"hs","s":["HIV and AIDS"]},{"k":"p","s":["UNAIDS estimated that in 2019 there were around 76,000 adults aged 15 or over in Burundi were living with HIV. The prevalence percentage was estimated at around 1% of the adult population compared to the prevalence percentage in adults in the UK of around 0.25%. Follow normal precautions to avoid exposure to HIV/AIDS."]},{"k":"hs","s":["Other health risks"]},{"k":"p","s":["An outbreak of cholera continues in Burundi. Take precautions and get urgent medical attention if you become unwell."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Burundi"]},{"k":"p","s":["There are 3 hospitals in Bujumbura that provide medical care for serious accidents:"]},{"k":"li","s":["Kira Hospital"]},{"k":"li","s":["Hôpital Militaire de Kamenge"]},{"k":"li","s":["Médecins Sans Frontières in Prince Régent Charles Hospital"]},{"k":"p","s":["Outside Bujumbura, there is a lack of adequate medical facilities and medical evacuation to Kenya or Rwanda may be needed."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Burundi","https://www.gov.uk/government/publications/burundi-list-of-medical-facilitiespractitioners/burundi-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Burundi"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"p","s":["You can also request help from the Red Cross by calling 109."]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=burundi"],", and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=burundi"]," in Burundi"]},{"k":"li","s":["dealing with a ",["death in Burundi","https://www.gov.uk/government/publications/burundi-bereavement-information-pack"]]},{"k":"li","s":["being ",["arrested or imprisoned in Burundi","https://www.gov.uk/government/publications/burundi-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/burundi/british-embassy-office-bujumbura"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/burundi/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":17490,"change":"Addition of information about a declaration of an Ebola outbreak in DRC on 15 May (‘Health page’)."},"https://www.gov.uk/foreign-travel-advice/belize":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"0a70447dcc38a25e94b67124f5cd77ef6ea4d822baa85edaf03e17581fe43fb3","read":"https://www.gov.uk/api/content/foreign-travel-advice/belize","bytes":56806,"x":"fulltext v1","title":"Belize travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-24T00:00:00+00:00","mod":"2026-11-05T16:48:48+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["State of Emergency"]},{"k":"p","s":["The Government of Belize announced a 30-day State of Emergency (SoE) on 1 November in parts of Belize City and the Belize and Cayo Districts following an increase in gang-related violence."]},{"k":"p","s":["The state of emergency gives law enforcement additional powers to restore order and maintain public safety in affected communities. There may be an increased police presence and more checkpoints in affected areas."]},{"k":"p","s":["Belize City and Belize District"]},{"k":"li","s":["the Southside and Westside of Belize City"]},{"k":"li","s":["northern parts of Belize City, including the Philip Goldson Highway to Ladyville"]},{"k":"li","s":["Lord’s Bank"]},{"k":"li","s":["Los Lagos"]},{"k":"li","s":["Lake Gardens"]},{"k":"li","s":["Vista del Mar"]},{"k":"p","s":["Cayo District"]},{"k":"li","s":["Cotton Tree Village, including all streets and residential areas running parallel to the George Price Highway"]},{"k":"li","s":["Unitedville Village, including all streets and residential areas running parallel to the George Price Highway"]},{"k":"p","s":["Carry valid ID and remain vigilant. Follow the instructions of local authorities and monitor local media for updates."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/belize/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Belize’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Belize set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Belize High Commission in the UK","https://belizehighcommission.co.uk/"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Belize, your passport must have an ‘expiry date’ more than 3 months after the date you arrive. Some airlines may refuse boarding if the expiry date is not more than 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider to make sure your passport and other travel documents meet their requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Immigration and customs declaration form"]},{"k":"p","s":["All travellers transiting Belize through the Philip Goldson International Airport are required to complete an immigration and customs declaration form. Whilst paper declarations will still be accepted during the phased transition to a fully digital system, the Belizean authorities recommend completing the ",["digital form","https://belizetravel.immigration.gov.bz/Belize_Digital_Forms/"]," prior to travel."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Belize without a visa for 30 days."]},{"k":"p","s":["If you want to extend your stay, it will cost 200 Belize dollars for each additional 30 days. You should go to the nearest office of the ",["Belize Immigration and Nationality Department","https://immigration.gov.bz/permits/visitors-permit/"]," and request a new stamp."]},{"k":"h","s":["Departure tax"]},{"k":"p","s":["If you leave Belize by land, or by water crossing to Guatemala or Mexico, you must pay a departure tax of 40 Belize dollars or 20 US dollars at the border. If leaving by air, the tax is usually included in the airfare."]},{"k":"h","s":["Travelling with children"]},{"k":"p","s":["Children aged 17 and under who are travelling on their own, or with an adult who is not their parent, must carry a notarised letter to prove parental responsibility, or consent to travel from the parent or guardian. Children travelling with one parent must also have a notarised letter of authority from the other parent giving consent for travel."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Belize guide","https://travelhealthpro.org.uk/country/26/belize"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Belize. You must declare anything that may be prohibited or subject to tax or duty. Items that need to be declared will be listed on the customs declaration form. Contact the ",["Belize Customs and Excise Administration","https://www.customs.gov.bz/contact.html"]," for more information."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Belize"]},{"k":"p","s":["Although there is no recent history of terrorism in Belize, attacks cannot be ruled out."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Political demonstrations take place in Belize City and Belmopan, but most are peaceful. Follow the instructions of local authorities, monitor local media and avoid large gatherings and demonstrations."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Investigations can take several weeks, police capacity is limited and most crimes remain unsolved and unprosecuted."]},{"k":"p","s":["Belize has one of the highest per capita murder rates in the world. Other violent crime, including armed robbery, shootings, domestic abuse and sexual assault are also a concern."]},{"k":"p","s":["Serious gang-related violence occurs most frequently in Belize City, particularly in the area to the south of the Haulover Creek (known as Southside). Tourists are not normally the targets of gang violence, but anyone near an incident could be affected. You should:"]},{"k":"li","s":["follow the advice of your hotel and local authorities"]},{"k":"li","s":["be watchful of your surroundings"]},{"k":"p","s":["Armed criminals have been active in the remote forested areas of Belize, particularly the border area with Guatemala and close to tourist sites there. However, the area is patrolled by the Belize Defence Force and there have been no reported incidents involving tourists."]},{"k":"p","s":["Tourists, in general, are vulnerable to theft of cash, credit cards, phones and other personal belongings, including in tourist destinations such as San Pedro, Caye Caulker, Placencia and San Ignacio. You should:"]},{"k":"li","s":["avoid dark alleys"]},{"k":"li","s":["use ATMs located in well-lit public areas or inside a bank or business"]},{"k":"li","s":["keep valuables out of sight"]},{"k":"li","s":["be aware that wearing expensive jewellery could attract attention"]},{"k":"li","s":["use a qualified guide for trips off the beaten track"]},{"k":"li","s":["only use accommodation and campgrounds that appear genuine and established"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Possession of illegal drugs can lead to a fine and prison sentence."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex activity between consenting adults is legal. The Immigration Act prohibits “homosexual” persons from entering the country but immigration authorities have not enforced that law. Tourist-friendly areas, including San Pedro and Ambergris Caye, are relatively open and welcoming to the LGBT+ community. Outside of these areas, LGBT+ couples, especially men, tend to be reluctant to display affection in public because of incidents of verbal or physical abuse which have been reported."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"p","s":["Find more information on local travel from the Belize Tourism Board."]},{"k":"hs","s":["Swimming safety"]},{"k":"p","s":["There have been injuries and fatalities from adventure sports activities, including snorkelling and diving. The main causes have been inadequate safety precautions and severe weather conditions. Check local weather forecasts and only use registered and licensed operators."]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Belize, see information on ",["driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Belize for up to 3 months. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"],". For longer stays, you must get a Belize driving permit from the ",["Department of Transport","https://bmvrals.gov.bz/portal/"]," in your district."]},{"k":"p","s":["Driving conditions may be hazardous, especially during the rainy season, due to:"]},{"k":"li","s":["roads with potholes, unpaved dirt shoulders and few lane markings"]},{"k":"li","s":["narrow or unpaved roads"]},{"k":"li","s":["roads often unlit"]},{"k":"li","s":["lack of emergency road assistance"]},{"k":"li","s":["flooded temporary bridges and causeways during severe weather in southern parts of the country, particularly in Stann Creek and Toledo."]},{"k":"hs","s":["Driving standards"]},{"k":"p","s":["Road traffic accidents are common. Local driving and vehicle maintenance standards are poor. Public buses are not well maintained and many do not have seatbelts. Take care when driving, particularly during rainy conditions or at night. Be aware of the risks, including high levels of drink-driving, speeding, reckless driving and other vehicles, including bicycles, not having working lights."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Only take registered taxis with green licence plates. Always ask the fare before getting in, and expect to pay in cash."]},{"k":"hs","s":["Air Travel"]},{"k":"p","s":["Following the hijacking of a small passenger aircraft on an internal flight on 17 April 2025, the Belize Airports Authority has announced security enhancements across Belize’s municipal airstrips. You may wish to allow extra time in case of disruption to domestic air travel."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Hurricanes"]},{"k":"p","s":["The hurricane season is from 1 June to 30 November. Monitor local and international weather updates from the ",["US National Hurricane Center’s regional map","https://www.nhc.noaa.gov/"]," and the ",["National Meteorological Service of Belize","https://nms.gov.bz/"],". You should also follow advice from the National Emergency Management Organisation."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Heavy rainfall can cause flooding. Follow the weather forecasts from the National Hydrological Service and the ",["National Meteorological Service of Belize","https://nms.gov.bz/"],"."]},{"k":"p","s":["Flooding caused by Tropical Storm Sara is affecting western parts of Belize. You should follow the advice of the local authorities."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["Belize is not directly affected by earthquakes, but tremors from earthquakes in neighbouring countries can occasionally be felt in Belize. There can occasionally be tsunami warnings."]},{"k":"p","s":["The US Federal Emergency Management Agency has advice about what to do before, during and after an earthquake."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 911 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Belize","https://travelhealthpro.org.uk/country/26/belize#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Belize","https://travelhealthpro.org.uk/country/26/belize"],", including:"]},{"k":"li","s":["Zika virus"]},{"k":"li","s":["chikungunya virus"]},{"k":"li","s":["dengue"]},{"k":"li","s":["malaria"]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Belize"]},{"k":"p","s":["Medical facilities in Belize are limited and availability of prescription medicine is unreliable. Serious medical cases are normally evacuated to the US, at the patient’s expense."]},{"k":"p","s":["FCDO has a ",["list of medical facilities in Belize","https://www.gov.uk/government/publications/belize-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Belize","https://www.gov.uk/guidance/living-in-belize#healthcare"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Belize"]},{"k":"p","s":["Telephone: 911 or 90 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=belize"]," and ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Belize"]," in Belize"]},{"k":"li","s":["dealing with a ",["death in Belize","https://www.gov.uk/government/publications/belize-bereavement-packinformation"]]},{"k":"li","s":["being ",["arrested or imprisoned in Belize","https://www.gov.uk/government/publications/belize-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/belize/british-high-commission-belmopan"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/belize/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":13630,"change":"New information following the Government of Belize announcing a 30-day State of Emergency ('Warnings and insurance' page)."},"https://theconversation.com/albertans-soundly-vote-to-stay-in-canada-many-are-asking-why-they-had-to-vote-in-the-first-place-294396":{"r":"conversation","at":"2026-11-17T16:30Z","sha":"9ceb719a2a2e98ebd7ccc91b4bb4e0467f8cafa178f24bc4a8c6beb7b0661e41","read":"https://theconversation.com/albertans-soundly-vote-to-stay-in-canada-many-are-asking-why-they-had-to-vote-in-the-first-place-294396","bytes":190961,"x":"fulltext v1","title":"Albertans soundly vote to stay in Canada. Many are asking why they had to vote in the first place","by":[{"n":"Jared Wesley","r":"Professor, Political Science, University of Alberta"}],"pub":"2026-10-20T19:11:50Z","mod":"","blocks":[{"k":"p","s":["Unofficial results from the Alberta independence referendum indicate a ",["resounding victory for the remain side","https://www.ctvnews.ca/edmonton/alberta-referendum/article/albertans-vote-to-reject-a-referendum-on-separation/"],". Three in four voters chose to stay in Canada."]},{"k":"p","s":["The ",["50-point margin","https://www.cbc.ca/news/canada/edmonton/livestory/alberta-referendum-results-live-updates-separatism-october-19-2026-9.7387777"]," is the largest of its kind in similar secession referendums. Most questions with answers this clear are never asked in the first place."]},{"k":"p","s":["How did a vote that ",["captured so much attention around the world","https://theconversation.com/in-alberta-far-right-populism-fuelled-by-conspiracy-theories-and-alienation-drive-bid-to-separate-from-canada-294374"]," end in such a lopsided result? Blown out at the polls, what lies ahead for the separatist movement in Alberta? To understand this, we need to appreciate the power of far-right populism in the province."]},{"k":"h","s":["The role of far-right populism"]},{"k":"p","s":["Separatists constitute a far-right populist movement in Alberta — a loose network of anti-establishment, anti-pluralist factions that have more in common with the MAGA movement in the United States than they do with secessionist movements elsewhere in the world."]},{"k":"p","s":[["Far-right populism","https://www.illiberalism.org/ruth-wodak-on-far-right-populism-and-shame/"]," is a worldview that divides society into virtuous people, on one hand, and dangerous outsiders on the other. The outsiders threaten ordinary folks’ ways of life and livelihoods from above (corrupt and distant elites) and beyond (immigrants, globalists)."]},{"k":"p","s":["In this mindset, liberal democratic institutions are rigged against the public interest and must be weakened, captured or eliminated. In short, far-right populism sees the true will of the people distorted or thwarted by strangers who control “the system.”"]},{"k":"p","s":["In Alberta separatist circles, ",["the main villains are federal government operatives — and the federal system itself — along with immigrant outsiders","https://canadiandimension.com/articles/view/alberta-separatism-is-a-tool-for-building-far-right-power-beyond-the-referendum"],". In their view, after more than a decade of sending members of Parliament to sit on the opposition benches to watch idly while Justin Trudeau’s Liberal government ran roughshod over the province, most Alberta separatists have given up hope of the Conservative Party forming a national government."]},{"k":"p","s":["To them, becoming an independent country was the only way to undo legislative changes they view as threatening Alberta’s economy and culture — increased immigration, environmental regulations, brakes on oil and gas production, progressive social programs, wealth redistribution out of the province."]},{"k":"p","s":["Read more: ",["Albertans disapprove of Donald Trump — and his brand is weakening separatism, too","https://theconversation.com/albertans-disapprove-of-donald-trump-and-his-brand-is-weakening-separatism-too-292573"]]},{"k":"h","s":["Unpopular in Alberta"]},{"k":"p","s":["While western alienation is ",["deeply rooted in Alberta’s political DNA","https://theconversation.com/qanda-with-an-alberta-politics-expert-taking-the-provinces-pulse-on-the-eve-of-the-referendum-294417"],", the separatist solution has been unpopular for generations."]},{"k":"p","s":["Separatist parties ",["have only ever elected one member to the provincial legislature","https://www.csmonitor.com/1982/0219/021945.html"]," (a brief stint following a byelection in 1982). Public opinion polls show ",["support for forming an independent country has ranged between 10 and 25 per cent","https://www.pbs.org/newshour/world/how-alberta-separatism-went-from-fringe-cause-to-referendum"]," throughout much of the past quarter century in Alberta."]},{"k":"p","s":["Even on the ",["eve of the referendum call","https://cground.substack.com/p/alberta-separatism-is-louder-than"],", barely one in five Albertans indicated support for forming a new country. Of these citizens, a sizeable proportion regarded support for separatism as a means to other ends, aimed at sending a message to the rest of Canada that Albertans are unhappy with their treatment in Confederation."]},{"k":"p","s":["So how did the views of a small minority manage to capture the political agenda? As with the rise of far-right populism in the United States and United Kingdom, ",["the answer has much to do with internal party politics","https://doi.org/10.31389/lseppr.4"],". The future of both separatism and far-right populism will now depend on how Alberta Premier Danielle Smith manages her party’s coalition in the days ahead."]},{"k":"h","s":["‘Grassroots’ UCP"]},{"k":"p","s":[["The United Conservative Party (UCP) has governed Alberta since 2019","https://globalnews.ca/news/5175344/alberta-election-jason-kenney-ucp-wins/"],". Formed by the merger of conventional Progressive Conservatives and the right-wing Wildrose Party, the UCP attempted to blend the popularity of the PCs with the populist impulses of Wildrose."]},{"k":"p","s":["Dubbing itself a “ ",["grassroots party","https://www.sherwoodparknews.com/opinion/columnists/opinion-grassroots-ucp-out-of-control-2"],",” the organizational structure provided unprecedented access to the leader. ",["Article 5.7 in the party’s bylaws","https://unitedconservative.ca/wp-content/uploads/UCP-Bylaws-Nov2024.pdf"]," allows a small group of activists to effectively replace the leader after a vote of non-confidence."]},{"k":"p","s":["These measures hold the leader’s feet to the fire. The UCP’s first leader, former premier Jason Kenney, discovered this near the end of the COVID-19 pandemic. Motivated by the success of the so-called ",["Freedom Convoy movement","https://policyoptions.irpp.org/2022/02/three-deep-seated-drivers-of-the-convoy-and-what-we-can-do-about-them/"],", a far-right faction within the party ousted him in favour of their preferred leader, Smith."]},{"k":"p","s":["Since then, Smith herself has been beholden to this most active portion of her party’s increasingly powerful base, whose policy objectives are drawn largely ",["inspired by MAGA","https://www.nytimes.com/2025/04/14/world/canada/canada-danielle-smith-trump.html"],"."]},{"k":"p","s":["Since extracting ",["major policy changes to limit transgender and voting rights","https://www.cbc.ca/news/canada/edmonton/alberta-legislature-bill-of-rights-transgender-policy-1.7364467"],", the far-right populists’ biggest demand of Smith has been to hold an independence referendum — something they have ",["negotiated with American Republicans","https://www.theglobeandmail.com/canada/article-alberta-separatism-canada-united-states-republican/"],". Officials in U.S. President Donald Trump’s administration have ",["not so subtly supported","https://www.cbc.ca/news/canada/calgary/trump-cabinet-member-weighs-in-on-alberta-separatism-9.7058082"]," these efforts."]},{"k":"p","s":["Smith amended legislation to ",["make it easier for separatists","https://nationalpost.com/news/politics/smith-lowers-bar-for-alberta-referendum-with-separatism-sentiment-emerging"]," to petition the government to hold a referendum. When the courts stepped in to prevent the separation petition from proceeding on the grounds it ",["breached First Nations treaty obligations","https://yellowheadinstitute.org/2026/inseparable-the-continuity-of-treaty-relationality-in-the-prairies/"],". Smith called the referendum anyway but softened the question, asking if Alberta should remain in Canada or proceed to a second binding provincial referendum on whether the province should separate."]},{"k":"h","s":["Other questions"]},{"k":"p","s":["In a move reminiscent of ",["former British prime minister David Cameron’s position on Brexit","https://ukandeu.ac.uk/why-david-cameron-called-the-2016-referendum/"],", Smith positioned herself as a champion of the “remain” side. Unlike Cameron’s side, hers won."]},{"k":"p","s":["Smith chose to table more than one question as part of Alberta’s referendum, however. Nine others received their own ballots, including five dealing with the treatment of immigrants in Alberta and four dealing with proposed changes to Canada’s Constitution."]},{"k":"p","s":["Smith campaigned for the “yes” side on these questions which, if passed, would empower her government to wrest control over immigration from Ottawa, restrict immigrants’ access to public services and seek a major devolution of powers from the federal government to the provinces."]},{"k":"p","s":["At the time of writing, the “yes” side ",["is ahead","https://results.elections.ab.ca/8400"]," by slim margins on most but not all of these nine questions. This suggests Albertans are comfortable staying within Canada — but less comfortable about the province’s power within it."]},{"k":"h","s":["What next?"]},{"k":"p","s":["It’s clear the referendum results are a rejection of the separatist belief that Canada is irreparably broken. Most Albertans view it as fixable and worth repairing."]},{"k":"p","s":["At the same time, the fact that initial results suggest a slim majority of voters want Alberta to reduce immigrants’ access to healthcare and education reveals the limits of their tolerance for pluralism."]},{"k":"p","s":["Smith’s post-referendum message called for unity and set her agenda for the year ahead, which by law must include a provincial election."]},{"k":"p","s":["“Let us move forward not as a people divided by how we voted … but as neighbours, friends, Albertans and Canadians,” she said. “Let us treat one another with respect and compassion. Let us stand proudly for this province.”"]},{"k":"p","s":["But does she view the outcome as a call to rebalance federalism or a mandate for internal provincial reform? Will she pursue formal constitutional negotiations or use the outcome as leverage for non-constitutional changes?"]},{"k":"p","s":["The UCP’s far-right populists will likely push her to pursue major reforms to the Constitution. To them, problems with healthcare and education are attributable not just to a flawed immigration system, but to immigrants themselves."]},{"k":"p","s":["Separatists must now choose between fighting within the UCP or through new parties. To build momentum for a future referendum, they may leverage failed constitutional gambits and immigration reforms to argue Canada cannot accommodate Alberta."]},{"k":"p","s":["Albertans will vote on these issues in the next election. That election campaign — and the clash between far-right populists and moderate pluralists — is already under way. The referendum only inflamed existing tensions."]}],"chars":7776},"https://theconversation.com/the-surprising-origins-of-denmarks-reputation-for-open-mindedness-281583":{"r":"conversation","at":"2026-11-17T16:30Z","sha":"3521071651e80c314d4be50c57dcddbda7f794a2c9bf9f6d6602eb84cd7ff436","read":"https://theconversation.com/the-surprising-origins-of-denmarks-reputation-for-open-mindedness-281583","bytes":179311,"x":"fulltext v1","title":"The surprising origins of Denmark’s reputation for open-mindedness","by":[{"n":"Detlef Siegfried","r":"Professor of Modern German and European History, University of Copenhagen"}],"pub":"2026-11-09T12:51:30Z","mod":"","blocks":[{"k":"p","s":["Ask Danes what makes Denmark Danish and you might hear about openness, tolerance and the freedom to live as you choose."]},{"k":"p","s":["You can see it in the country’s history: ",["Denmark","https://theconversation.com/topics/denmark-2806"]," was the first country in the world to legalise pornography. ",["Alternative communities such as Christiania","https://dac.dk/en/magazine/places/christiania-from-hippie-colony-to-alternative-community-10"]," in Copenhagen are internationally famous for their counterculture and liberal attitudes. And ",["Danish activists","https://www.nytimes.com/2011/10/31/world/europe/axel-axgil-danish-advocate-for-gay-rights-dies-at-96.html"]," have helped push ideas about sexuality and family life in new directions."]},{"k":"p","s":["But there is a less obvious part of this story."]},{"k":"p","s":["Denmark did not develop its reputation for open-mindedness entirely on its own. Some of the people who helped create that image were looking at Denmark from across the border."]},{"k":"p","s":["From the 1960s onwards, West Germany became an important audience for Denmark’s emerging reputation as a more liberal society. For young Germans frustrated with what they saw as a conservative, hierarchical and authoritarian society, Denmark looked like a place where people had more freedom to experiment with different ways of living."]},{"k":"p","s":["West Germany in the 1960s and 1970s was still grappling with the legacy of Nazism. Many young people in the West German New Left rejected the social and political values of their parents’ generation and looked for alternatives."]},{"k":"p","s":["The situation was also different across the German divide. In East Germany, the communist state offered its own very different model of society and controlled many aspects of public and private life."]},{"k":"p","s":["For young West Germans seeking alternatives, Denmark seemed like something else entirely: a nearby democratic country where social experimentation seemed possible."]},{"k":"p","s":[["Research","https://engerom.ku.dk/forskning/det-danske-frisind-set-med-danske-og-tyske-oejne/"]," I am carrying out with my colleague Tobias Haimin de Fønss Wung-Sung into West German reactions to Denmark during this period shows how several aspects of Danish life contributed to this image."]},{"k":"p","s":[["Christiania, the self-governing community","https://www.tandfonline.com/doi/full/10.1111/j.1467-9906.2012.00608.x"]," in Copenhagen, became associated with communal living and alternative lifestyles. The New Left political movement challenged established politics and social norms. Roskilde music festival grew into an important gathering place for young people and counterculture. Denmark also experimented with progressive approaches to education and pornography."]},{"k":"p","s":["From abroad, this created ",["an image of Denmark","https://researchprofiles.ku.dk/da/publications/alternative-d%C3%A4nemark-kosmopolitismus-im-westdeutschen-alternativm/"]," as a country where people were unusually free to live differently."]},{"k":"h","s":["‘A porn paradise’"]},{"k":"p","s":["In 1969, when the Danish parliament legalised ",["pornographic images","https://www.cambridge.org/core/journals/central-european-history/article/trying-porn-in-1960s-austria/C5A2EFB7E1DE1920A5F48DFD4AD5F197"],", its decision was highly controversial among Danes. But it attracted considerable attention internationally, particularly in West Germany, where the new government under Chancellor Willy Brandt prepared a similar reform."]},{"k":"p","s":["The result was ",["not simply a change in Danish law","https://danmarkshistorien.lex.dk/Folketingsdebat_om_frigivelse_af_billedpornografien_1968-1969"],". People, products and money began moving across the border."]},{"k":"p","s":["Government officials travelled to Copenhagen to learn about the effects of the liberalisation. West Germans travelled to Denmark to buy pornography. Danish producers gained access to a much larger market south of the border. Denmark could even be imagined in West Germany as a kind of porn paradise."]},{"k":"p","s":["Our research into West German reactions to Denmark’s liberalisation between 1965 and 1985 shows how the country became associated with a new kind of sexual freedom."]},{"k":"p","s":["Danish homosexual people and activists also developed connections with larger gay communities in West Germany, particularly in Berlin and Hamburg. And Denmark developed its own naturist culture, not least inspired by the German movement of freikörperkultur (pronounced FRY-kur-per-kul-toor) or “free body culture”. People gathered to swim, sunbathe and socialise naked."]},{"k":"p","s":["People, ideas and practices were therefore moving in both directions across the border."]},{"k":"h","s":["Reputation and national values"]},{"k":"p","s":["Over time, these developments helped turn Denmark’s reputation for social liberalism into something more than an international image. It became part of how Denmark could describe itself."]},{"k":"p","s":["In 2016, for example, the Danish government asked the public to identify values considered particularly important to Danish society. The resulting ",["Danmarkskanon, or Danish Canon","https://faktalink.dk/emner/danmarkskanon#baggrund"],", included ten such values. One was frisind (pronounced free-sin) – a word that can mean open-mindedness, tolerance or freedom from conventional moral constraints."]},{"k":"p","s":["The Canon described frisind in terms of openness towards traditional moral ideas, the body and sexuality. It pointed to Denmark’s relaxed attitude towards nudity, tolerance of different forms of family and sexual life, alternative lifestyles and the legalisation of pornography."]},{"k":"p","s":["By this point, what had once been a contested and internationally shaped reputation had become something that could be presented as part of Denmark’s cultural heritage. But that does not necessarily mean Danes have always been uniquely tolerant."]},{"k":"p","s":["The Danish criminologist ",["Berl Kutchinsky","https://lex.dk/Berl_Kutchinsky"]," (1935-1995) studied the liberalisation of pornography extensively and he was sceptical of precisely this idea. He argued that Denmark’s exceptional liberalism was something of a myth."]},{"k":"p","s":[["In his view","https://tidsskrift.dk/psyke/article/view/134326"],", Danes still belonged to the broadly “puritanical, post-Victorian” family of European nations. Denmark was simply among the less puritanical members of that group, alongside Sweden, the Netherlands and Germany. Compared with them, he considered Danes “slightly more liberal and permissive” when it came to sexuality."]},{"k":"p","s":["If Kutchinsky was right, Danish frisind is less about being uniquely liberal than about being liberal in comparison with particular neighbours."]},{"k":"h","s":["Somewhere else"]},{"k":"p","s":["The history of Danish frisind therefore stretches well beyond Denmark."]},{"k":"p","s":["And while it has been shaped by changing laws and attitudes inside the country, people travelling across the border, activists building international networks and products finding new markets have also played a role."]},{"k":"p","s":["That is easy to lose sight of once an idea becomes part of a national identity."]},{"k":"p","s":["The Danish Canon presents frisind as a Danish value. But its history suggests something more complicated: Denmark’s reputation for open-mindedness was, at least partly, made through its relationships with other countries."]},{"k":"p","s":["In other words, one of the very things Denmark considers particularly Danish likely started out more as a comparison with somewhere else."]},{"k":"p","s":["This article was commissioned as part of a partnership between ",["Videnskab.dk","https://videnskab.dk/"]," and The Conversation. Articles are also published in Danish."]}],"chars":6282},"https://theconversation.com/uk-appoints-new-climate-security-envoy-heres-what-she-could-change-296525":{"r":"conversation","at":"2026-11-17T16:38Z","sha":"ad6366955faa6d4b804f1d0c2adc51a4e1df4056b724be0b4ddeda6ed3db3631","read":"https://theconversation.com/uk-appoints-new-climate-security-envoy-heres-what-she-could-change-296525","bytes":179327,"x":"fulltext v1","title":"UK appoints new climate security envoy – here’s what she could change","by":[{"n":"James Dyke","r":"Assistant Director of the Global Systems Institute, University of Exeter"}],"pub":"2026-11-12T15:15:34Z","mod":"","blocks":[{"k":"p","s":["The UK government has just appointed Madeleine Alessandri as the world’s first special representative for climate security."]},{"k":"p","s":["Prime minister Andy Burnham announced the new role in his speech at the UN climate summit, Cop31, in Turkey. This, ",["he said","https://www.bbc.co.uk/news/live/c98r7xe5d38vt"],", would be part of “a new era of British leadership on climate”. He also cited climate as “a national security issue” – a sign that Burnham considers this environmental crisis a significant risk to the country’s social stability and economy."]},{"k":"p","s":[["With a remit","https://www.gov.uk/government/publications/uk-special-representative-for-climate-security-terms-of-reference"]," to “support ministers to champion UK leadership on climate and nature security”, ",["Alessandri","https://www.gov.uk/government/people/madeleine-alessandri"]," will report to the foreign secretary."]},{"k":"p","s":[["Climate change","https://theconversation.com/topics/climate-change-27"]," has long been considered as a ",["threat multiplier","https://www.un.org/en/climatechange/science/climate-issues/human-security"]," because it compounds and increases many risks to national security. Unfortunately, many governments have failed to acknowledge such threats, resulting in a ",["dangerous blind spot","https://www.ippr.org/articles/security-blind-spot"],"."]},{"k":"p","s":["For example, a warmer world will produce more erratic weather that will impact harvests. Less food produces price spikes. In order to try to ensure food security, governments implement export controls. This can cause globally traded food prices to spike driving people into ",["food poverty","https://theconversation.com/how-a-super-el-nino-could-trigger-global-famine-281486"],", exacerbate tensions and ",["lead to conflict","https://theconversation.com/three-reasons-why-the-climate-crisis-must-reshape-how-we-think-about-war-262469"],"."]},{"k":"p","s":["The ",["2026 UK harvest","https://theconversation.com/as-severe-drought-hits-the-uks-food-system-faces-crisis-heres-how-to-change-that-289417"]," is the ",["worst on record","https://eciu.net/media/press-releases/england-suffers-worst-harvest-on-record-comment"],". Four of the five worst harvests ",["have happened since 2020","https://www.theguardian.com/environment/2025/dec/04/record-heat-drought-2025-cost-uk-arable-farmers-estimated-800m-climate-crisis-grain-harvest"],". This ",["puts further pressure","https://www.bbc.co.uk/news/articles/c5rm9mdm79neo"]," on UK farmers."]},{"k":"p","s":["As climate security envoy, one of Alessandri’s priorities will need to be the state of ",["national food security","https://theconversation.com/the-uks-food-supply-is-more-fragile-than-you-might-think-heres-why-it-should-be-a-national-priority-270709"],". That’s because the ",["UK imports 40% of the food","https://www.gov.uk/government/publications/uk-food-security-index-2024/uk-food-security-index-2024"]," it consumes and so is extremely exposed to the tightening of global food supply."]},{"k":"p","s":["Given that this year’s ",["super El Niño","https://theconversation.com/topics/el-nino-5638"]," (when certain parts of the Pacific are warmer than usual) is already ",["creating havoc around the world","https://www.bbc.co.uk/weather/articles/c6dx07dznpyyo"],", Alessandri may soon find herself embroiled in efforts to ensure that the responses to the consequences of the climate crisis do not make the situation worse."]},{"k":"p","s":["Responding to extreme weather and climate consequences can produce ",["derailment risks","https://theconversation.com/the-worse-climate-change-gets-the-harder-it-becomes-to-stop-it-293987"]," whereby efforts to reduce climate change get blown off course by escalating climate and social destabilisation. For example, in response to rising food insecurity national governments can ban food exports. This increases food prices even further. Protests over the cost of living can spiral into wider unrest. All this can make it difficult to maintain the political will required to progress the energy transition."]},{"k":"p","s":["Read more: ",["Ecological myopia: the blind spot holding back climate action","https://theconversation.com/ecological-myopia-the-blind-spot-holding-back-climate-action-270912"]]},{"k":"h","s":["A gear change?"]},{"k":"p","s":["Alessandri is a career civil servant and the former chair of the UK’s ",["joint intelligence committee (JIC)","https://www.gov.uk/government/groups/joint-intelligence-committee"]," which oversees the UK’s secret intelligence services. Until now, the security implications of climate change sat within ",["Katie White","https://www.gov.uk/government/people/katie-white"],"’s remit as the UK’s ",["minister for climate transition","https://www.gov.uk/government/news/world-first-taskforce-to-protect-communities-from-climate-change"]," in the Department for Energy Security and Net Zero."]},{"k":"p","s":["It is perhaps no coincidence that it was the JIC that commissioned the ",["previously supressed","https://www.theguardian.com/environment/2026/sep/24/explainer-uk-climate-crisis-national-security-report-suppressed"]," ",["report","https://theconversation.com/a-uk-climate-security-report-backed-by-the-intelligence-services-was-quietly-buried-a-pattern-weve-seen-many-times-before-274325"]," on the national security implications of climate change. While published by the Department for Environment, Food and Rural Affairs, it is ",["widely acknowledged","https://www.bbc.co.uk/news/articles/ce9y1e09j72o"]," that the ",["national security assessment on global ecosystems","https://www.gov.uk/government/publications/nature-security-assessment-on-global-biodiversity-loss-ecosystem-collapse-and-national-security/national-security-assessment-on-global-ecosystems-accessible-version"]," was produced by the JIC while Allesandri was leading it."]},{"k":"p","s":["She will now be in a position to negotiate directly with other nations and organisations specifically about the food and wider security impacts of climate change. I would expect other governments to create similar roles in the near future because climate change is rapidly rising up the ranks of issues that are relevant to national security."]}],"chars":3512},"https://www.gov.uk/foreign-travel-advice/ukraine":{"r":"govuk","at":"2026-11-17T17:32Z","sha":"7bd44659ed196df5118f2ce3c7d4fafdccc6a768771a5e93849fc7716bdba6a8","read":"https://www.gov.uk/api/content/foreign-travel-advice/ukraine","bytes":102178,"x":"fulltext v1","title":"Ukraine travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-22T00:00:00+00:00","mod":"2026-10-02T09:30:25+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth and Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Crimea"]},{"k":"p","s":["FCDO advises against all travel to Crimea."]},{"k":"hs","s":["Border with Belarus"]},{"k":"p","s":["FCDO advises against all travel to within 50km of the border with Belarus in the following regions:"]},{"k":"li","s":["Volyn"]},{"k":"li","s":["Rivne"]},{"k":"li","s":["Zhytomyr"]},{"k":"p","s":["This is due to the ongoing presence of Russian and Belarusian military and security personnel on the Belarusian side of the border."]},{"k":"hs","s":["All other regions of Ukraine"]},{"k":"p","s":["FCDO advises against all travel to all other regions of Ukraine (with the exception of some Western regions; see below)."]},{"k":"h","s":["Areas where FCDO advises against all but essential travel"]},{"k":"p","s":["FCDO advises against all but essential travel to the following regions in western Ukraine:"]},{"k":"hs","s":["All parts:"]},{"k":"li","s":["Zakarpattia"]},{"k":"li","s":["Ivano-Frankivsk"]},{"k":"li","s":["Ternopil"]},{"k":"li","s":["Chernivtsi"]},{"k":"li","s":["Lviv"]},{"k":"hs","s":["Parts further than 50km from the border with Belarus:"]},{"k":"p","s":["(see Border with Belarus above)"]},{"k":"li","s":["Volyn"]},{"k":"li","s":["Rivne"]},{"k":"li","s":["Zhytomyr"]},{"k":"h","s":["Russian invasion of Ukraine"]},{"k":"p","s":["Russia continues to invade Ukraine. Russian missile and drone attacks take place frequently across the country. Attacks have killed and injured civilians and caused significant damage to civilian infrastructure, including residential, energy, industrial, rail and other related facilities. Russian military activity has intensified over the past year. Civilian casualties between January and August 2026 exceeded the total recorded in 2025."]},{"k":"p","s":["There is an ongoing risk of harm to British nationals from Russian attacks across Ukraine, including from missiles and drones that hit unintended targets or from falling debris. While these are more frequent where FCDO advises against all travel, they can and do also happen in the western regions, where FCDO advises against all but essential travel."]},{"k":"p","s":["British nationals should exercise heightened awareness and be prepared to take shelter immediately when an air alert is announced. Be extra vigilant whilst travelling in urban centres."]},{"k":"p","s":["Russian missile and drone attacks have struck government and civilian infrastructure across Ukraine, including public buildings, energy facilities, transport hubs, other critical infrastructure, residential areas and defence industrial sites. Conferences and events attended by the Ukrainian government and military are more likely to be targeted."]},{"k":"p","s":["Follow the advice of local authorities, including responding to air raid alerts and train evacuation instructions. Be prepared to seek shelter immediately and remain there for extended periods."]},{"k":"p","s":["Russian attacks on the energy network may result in unscheduled blackouts or emergency power cuts with little notice. Rolling scheduled blackouts may be required in some areas. Electricity outages may also affect district heating and water supplies. Be aware that temperatures may drop below -20°C during winter."]},{"k":"p","s":["Ukraine’s airspace remains closed."]},{"k":"p","s":["The situation in Ukraine can change quickly. Local rules and measures may change at short notice or without notification. FCDO cannot confirm that all information on this page reflects the latest situation in Ukraine."]},{"k":"h","s":["Support from the UK government"]},{"k":"p","s":["We continue to advise British nationals in regions where FCDO advises against all travel, to leave these areas, if they judge it safe to do so."]},{"k":"p","s":["The British Embassy in Kyiv is unable to help you in person. FCDO cannot facilitate your departure from Ukraine or your evacuation."]},{"k":"h","s":["If you are in Ukraine"]},{"k":"p","s":["Martial law is in place. Follow the instructions of the Ukrainian authorities and check any measures in place in your location, as they will vary by region."]},{"k":"p","s":["If you are in Ukraine, you should:"]},{"k":"li","s":["monitor local media for updates about security risks in your area"]},{"k":"li","s":["identify shelter locations in advance of any air alert"]},{"k":"li","s":["immediately take shelter if an air alert is announced"]},{"k":"li","s":["follow the directions of Ukrainian officials and first responders in the event of an emergency"]},{"k":"li","s":["take precautions including conserving water, food, and mobile phone charge and having warm clothing/sleeping bags to hand, and monitor local media for updates, including on power cut schedules"]},{"k":"li","s":["pay close attention to your personal security"]},{"k":"li","s":["avoid demonstrations and public gatherings"]},{"k":"li","s":["take extra care while moving around"]},{"k":"li","s":["know what curfews are in place"]},{"k":"p","s":["There are a number of air raid alert apps available, including ",["“Air Alert”","https://play.google.com/store/apps/details?id=com.ukrainealarm"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Monitor travel advice regularly. Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/ukraine/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"p","s":["See FCDO advice on ",["how to deal with a crisis overseas","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],"."]},{"k":"h","s":["Leaving Ukraine"]},{"k":"p","s":["Expect increased documentation checks, transport restrictions and increased security measures. Other measures could include additional border controls, restrictions on public events, curfews, restrictions on telephones, internet and broadcasting, and evacuations of certain areas."]},{"k":"p","s":["For information about leaving Ukraine by car, see ",["Transport information and risks","https://www.gov.uk/foreign-travel-advice/ukraine/safety-and-security#transport-information-and-risks"],"."]},{"k":"hs","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"p","s":["If you are a dual British-Ukrainian national or you have the right to reside in the UK, and want to leave Ukraine, contact the State Border Guard Service of Ukraine on adpsu@dpsu.gov.ua for advice."]},{"k":"p","s":["Ukrainian national and dual-national males aged 23 to 60 are prohibited from leaving the country. Dual-nationals have to comply to the same military conscription laws as Ukrainian mono-nationals."]},{"k":"p","s":["Even if you do not consider Ukrainian to be your primary nationality, the Ukrainian authorities may see you as a Ukrainian national: for example, if you have a Ukrainian parent, or if you were born in Ukraine."]},{"k":"p","s":["For any information regarding nationality issues, you would need to seek advice from local authorities or legal experts."]},{"k":"p","s":["The authorities in the countries bordering Ukraine set and enforce their entry rules. Before you travel, check the ",["foreign travel advice","https://www.gov.uk/foreign-travel-advice"]," for any countries you plan to travel through. If you need assistance from the UK government, contact the ",["British Embassy in that country","https://www.gov.uk/world/embassies"],"."]},{"k":"hs","s":["Assisted departure or evacuation"]},{"k":"p","s":["If you are in Ukraine against FCDO advice, or need support to leave Ukraine, take advice from a private security company and take appropriate security measures."]},{"k":"p","s":["FCDO cannot endorse or recommend any private security companies. Research whether a service provider will be suitable for your requirements and meets code of conduct and safety standards. The ",["Security in Complex Environments Group (SCEG)","https://www.sceguk.org.uk/"]," has several companies listed on their website. These companies have accredited certification for international standards."]},{"k":"p","s":["FCDO has not completed due diligence checks on these companies. FCDO does not accept any liability arising to any person for any loss or damage suffered through using these service providers or this information. FCDO is not able to provide financial assistance for employing private security or medical evacuation companies."]},{"k":"h","s":["British nationals fighting in Ukraine"]},{"k":"p","s":["If you travel to Ukraine to fight, or to assist others engaged in the war, your activities may amount to offences under UK legislation. You could be prosecuted on your return to the UK."]},{"k":"p","s":["Since 18 May 2024, British nationals who join the Armed Forces of Ukraine have to serve at least six months and are not allowed to leave Ukraine during this period."]},{"k":"p","s":["British nationals fighting in Ukraine have been killed or captured. British nationals undertaking humanitarian work have also been detained by Russian authorities. The risk to life, or of maltreatment, is high."]},{"k":"p","s":["The British Government’s ability to support you in these circumstances is very limited. It cannot facilitate your departure from Ukraine, your medical repatriation, or termination of your military contract. Find out more about ",["FCDO consular assistance","https://www.gov.uk/guidance/consular-assistance-how-the-foreign-commonwealth-development-office-provides-support"],"."]},{"k":"h","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel despite FCDO advice, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The FCDO provides advice about risks of travel to help British nationals make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK who choose to travel despite FCDO advice. It is based on the UK government’s understanding of Ukraine’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Ukraine set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Ukrainian Embassy in the UK","https://mfa.gov.ua/en/embassies/velika-britaniya"],". The Ukrainian State Border Guard Service has the final decision on whether a person is eligible to enter Ukraine."]},{"k":"h","s":["Permanent residents"]},{"k":"p","s":["If you are a permanent resident of Ukraine, you do not need to show proof of insurance."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["If you’re travelling without a visa, your passport should be valid for the proposed duration of your stay. No additional period of validity beyond this is required. If you’re applying for a visa, your passport may need to have an additional period of validity. Check with the ",["Ukrainian Embassy in the UK","https://mfa.gov.ua/en/embassies/velika-britaniya"]," for further details."]},{"k":"hs","s":["Additional requirements at the border"]},{"k":"p","s":["At the border you will need to:"]},{"k":"li","s":["complete an ",["immigration card","https://dpsu.gov.ua/en/poryadok-zapovnennya-immigracijnoyi-kartki"]]},{"k":"li","s":["scan your fingerprints as part of biometric data collection at border crossing points if requested by the immigration officer"]},{"k":"li","s":["have evidence of sufficient funds. You can show: cash"]},{"k":"li","s":["bank cards with bank statements"]},{"k":"li","s":["accommodation bookings"]},{"k":"li","s":["tourist vouchers"]},{"k":"li","s":["a letter of financial support from your sponsor"]},{"k":"li","s":["return or onward travel tickets"]},{"k":"p","s":["You can find more information on:"]},{"k":"li","s":[["Ukrainian Embassy in the UK","https://uk.mfa.gov.ua/en/consular-issues/4409-visa-requirements-for-foreigners-entering-ukraine"]]},{"k":"li","s":[["State Border Guard Service of Ukraine","https://dpsu.gov.ua/en/informaciya-dlya-inozemciv-ta-osib-bez-gromadyanstva"]]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["British Citizen passport holders can enter Ukraine without a visa for visits of up to 90 days within a 180-day period. Ukraine has confirmed that this policy will continue to apply to British citizens until 30 January 2027."]},{"k":"p","s":["If you’re planning to stay in Ukraine for longer than 90 days in a 180 day period, you need to get a visa. For more advice contact the ",["Ukrainian Embassy in London","https://mfa.gov.ua/en/embassies/velika-britaniya"]," or ",["Consulate General in Edinburgh","https://edinburgh.mfa.gov.ua/en"],"."]},{"k":"hs","s":["Expired residence cards"]},{"k":"p","s":["If you have a temporary or permanent residence card that’s expired, you are still allowed to return to Ukraine. The expired document will remain valid while martial law remains in place and for 30 days afterwards. For more information see the ",["Visit Ukraine website","https://visitukraine.today/blog/1063/an-expired-residence-permit-gives-the-right-to-enter-ukraine-new-conditions-and-exceptions"]," or contact the ",["State Migration Service of Ukraine","https://dmsu.gov.ua/en-home.html"],"."]},{"k":"hs","s":["Visa overstays"]},{"k":"p","s":["If you need to extend your stay in Ukraine, check with the State Migration Service. If you overstay the 90 day allowance, you will be fined and may not be able to return to Ukraine for 90 days after leaving the country."]},{"k":"h","s":["Non-government controlled areas"]},{"k":"p","s":["If you intend to go to any of the areas not controlled by the Ukrainian authorities, you must apply to the ",["State Migration Service","https://dmsu.gov.ua/en-home.html"],"."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Ukraine guide","https://travelhealthpro.org.uk/country/232/ukraine#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into and out of Ukraine","https://customs.gov.ua/en/"]," (in Ukrainian), including antiques and items of historical interest. You must declare anything that may be prohibited or subject to tax or duty. If in doubt seek prior permission from the ",["customs authorities","https://customs.gov.ua/en/contacts"],"."]},{"k":"hs","s":["Bringing your car to Ukraine"]},{"k":"p","s":["Non-residents are allowed to bring a vehicle for personal use into Ukraine for up to one year. There’s no need to complete a customs declaration form. The vehicle can only be used in Ukraine by the person that brought it into the country. An undeclared vehicle cannot be:"]},{"k":"li","s":["used for commercial purposes"]},{"k":"li","s":["dismantled"]},{"k":"li","s":["sold"]},{"k":"li","s":["rented to other people"]},{"k":"li","s":["used to travel through Ukraine"]},{"k":"p","s":["If you want to do any of these things, you’ll need to register the vehicle in Ukraine and pay the appropriate customs duty."]},{"k":"p","s":["You must take the vehicle out of Ukraine within the required timeframe, or place it into the customs regime of the State."]},{"k":"p","s":["If your vehicle breaks down and cannot be fixed, you should inform the State Customs Service and provide them with evidence that it cannot be repaired. You may then dispose of the vehicle through the official channels of the State Customs Service."]},{"k":"p","s":["For further information on bringing your car to Ukraine, ",["contact the State Customs Service of Ukraine","https://customs.gov.ua/contacts"],"."]},{"k":"h","s":["Crossing international borders"]},{"k":"p","s":["It is illegal to enter internationally recognised Ukrainian territory through a border point that is not currently controlled by the Ukrainian authorities. If you do, you risk arrest or a fine, and a travel ban."]},{"k":"p","s":["International border crossings that are not currently under the control of the Ukrainian authorities include:"]},{"k":"li","s":["all land border crossings into Donetsk region"]},{"k":"li","s":["all land border crossings and seaports in Luhansk region"]},{"k":"li","s":["all seaports in Kherson region east of the Dnipro river"]},{"k":"li","s":["all airports and seaports in Crimea and the Kerch Bridge road and rail crossing into Crimea"]},{"k":"p","s":["For information on border crossing procedures, entry and exit regulations, and checkpoints, see the ",["State Border Guard Service of Ukraine (SBGSU) website","https://dpsu.gov.ua/en/"],"."]},{"k":"h","s":["Leaving Ukraine at international borders"]},{"k":"p","s":["For information on leaving Ukraine by car, see ",["Transport information and risks","https://www.gov.uk/foreign-travel-advice/ukraine/safety-and-security#transport-information-and-risks"],"."]},{"k":"hs","s":["Travelling from Ukraine to Poland"]},{"k":"p","s":["If you plan to travel to Poland, check the ",["travel advice page for Poland","https://www.gov.uk/foreign-travel-advice/poland"]," which includes information on entry requirements."]},{"k":"p","s":["The Ukrainian government website lists the ",["main border crossings into Poland","https://dpsu.gov.ua/en/map"],"."]},{"k":"hs","s":["Travelling from Ukraine to Hungary"]},{"k":"p","s":["If you plan to travel to Hungary, check our ",["travel advice page for Hungary","https://www.gov.uk/foreign-travel-advice/hungary"],", which includes information on entry requirements."]},{"k":"p","s":["The Hungarian police website gives more information on ",["crossing the Ukraine-Hungary border","https://www.police.hu/en/content/border-crossing"],"."]},{"k":"hs","s":["Travelling from Ukraine to Slovakia"]},{"k":"p","s":["If you plan to travel to Slovakia, check our ",["travel advice for Slovakia","https://www.gov.uk/foreign-travel-advice/slovakia"],", which includes information on entry requirements."]},{"k":"p","s":["For information about cross-border rail connections, see the ",["Slovak national rail website","https://www.zssk.sk/en/"],". For information on crossing the border see ",["Slovak government advice","https://www.minv.sk/?the-state-border-crossing"],"."]},{"k":"hs","s":["Travelling from Ukraine to Romania"]},{"k":"p","s":["If you plan to travel to Romania, check our ",["travel advice for Romania","https://www.gov.uk/foreign-travel-advice/romania"],", which includes information on entry requirements."]},{"k":"hs","s":["Travelling from Ukraine to Moldova"]},{"k":"p","s":["If you plan to travel to Moldova, check our ",["travel advice for Moldova","https://www.gov.uk/foreign-travel-advice/moldova"],", which includes information on entry requirements."]},{"k":"p","s":["FCDO advises against all travel to Transnistria."]},{"k":"h","s":["Border with Belarus"]},{"k":"p","s":["Ukraine’s border with Belarus is currently closed."]},{"k":"p","s":["FCDO advises against all travel to Belarus. See ",["FCDO Travel Advice for Belarus","https://www.gov.uk/foreign-travel-advice/belarus"],"."]},{"k":"h","s":["Border with Russia"]},{"k":"p","s":["Ukraine’s border with Russia is currently closed."]},{"k":"p","s":["FCDO advises against all travel to Russia. See ",["FCDO Travel Advice for Russia","https://www.gov.uk/foreign-travel-advice/russia"],"."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/ukraine/warnings-and-insurance"]," and ",["regional risks advice","https://www.gov.uk/foreign-travel-advice/ukraine/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Ukraine"]},{"k":"p","s":["Terrorist attacks in Ukraine cannot be ruled out."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["A state of emergency, put in place by the Government of Ukraine in February 2022, remains in effect, and martial law is in force throughout Ukraine."]},{"k":"h","s":["Unexploded weapons"]},{"k":"p","s":["There is a hazard from unexploded weapons throughout Ukraine, but particularly in the South and East of the country along the current conflict frontlines, and in areas where ground fighting occurred (particularly since 2022). Drone and missile strikes occur frequently across Ukraine and can deposit unexploded weapons in public areas. This includes cluster munitions, which scatter round the landing site and can cause delayed explosions. Flooding in the Kherson Oblast, following the destruction of the Kakhovka Dam in June 2023, spread unexploded weapons across the region."]},{"k":"p","s":["If you come across an unexploded weapon, such as a landmine, do not approach it or touch it. Make a note of where you saw it and notify the authorities on 101. Beware of more unexploded weapons nearby."]},{"k":"h","s":["Zaporizhzhia Nuclear Power Plant"]},{"k":"p","s":["Explosions continue to be reported near the area of the Zaporizhzhia Nuclear Power Plant indicating ongoing military activity. There have been no reports of any radiation release."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Before the full-scale invasion, serious crime against foreigners was relatively rare, but incidents did occur, with some cases being racially motivated."]},{"k":"p","s":["If you are a victim of crime, report it to the police by calling 102. FCDO has ",["a list of local translators in Ukraine","https://www.gov.uk/government/publications/ukraine-list-of-interpreters"],". We cannot confirm whether these translators are still offering services during Russia’s invasion of Ukraine."]},{"k":"hs","s":["Protecting your belongings"]},{"k":"p","s":["Be alert to the possibility of street crime and petty theft. Foreigners may appear to be lucrative targets."]},{"k":"p","s":["Theft of and from vehicles is common. Do not leave documents or money in your vehicle."]},{"k":"hs","s":["Drink and food spiking"]},{"k":"p","s":["Do not leave drinks or food unattended as they could be spiked. Beware of accepting drinks from casual acquaintances."]},{"k":"hs","s":["Scams"]},{"k":"p","s":["Cloning of credit and debit cards is common. Be aware of who is around you when using ATMs and do not let your card out of your sight during transactions."]},{"k":"hs","s":["Cyber attacks"]},{"k":"p","s":["Ukraine is a target for large cyber-attacks which disrupt basic services and risk data security, including personal data. In March 2025, a large-scale attack targeted Ukraine’s national railway operator Ukrzaliznytsia, impacting ticket purchasing."]},{"k":"p","s":["In December 2023, there was a high-impact cyber attack on Ukrainian networks. Ukraine’s largest mobile network operator, Kyivstar, suffered a cyber attack which left users without a mobile signal or the ability to use the internet. It also disrupted air raid apps, some banks, ATMs, and point-of-sale terminals. The Ukrainian bank Monobank was also targeted, disrupting access to the bank’s website."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Language"]},{"k":"p","s":["Ukrainian officials generally only speak Ukrainian and Russian."]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Carry your passport at all times to use as identification and to demonstrate your legal status in Ukraine if asked by the police. Police should identify themselves and show identification. If you’re detained because you have not been able to present your passport, ask for an official report."]},{"k":"hs","s":["Access to money"]},{"k":"p","s":["ATMs are available and credit cards are widely used in cities. However, as a result of the current invasion of Ukraine by Russia, ATMs might not be refilled with cash and some bank cards might not be accepted. During power cuts, ATMs and card terminals may not work."]},{"k":"p","s":["Make sure you have sufficient cash in local currency. US dollars and euros are the easiest currencies to exchange in Ukraine. You may be able to exchange sterling, but in fewer places. Scottish and Northern Irish notes are not accepted. Only use official exchange booths and make sure you’re given a receipt. You’ll need to present your passport to exchange currency worth 150,000 Ukrainian hryvnia or more. You’ll need the receipt to exchange money back on departure."]},{"k":"p","s":["There is a risk that cyber attacks could disrupt mobile, internet and banking services."]},{"k":"hs","s":["Alcohol and smoking"]},{"k":"p","s":["It is illegal to smoke or drink alcohol in public places, including on public transport, at bus stops, underground crossings, cultural, sports and governmental establishments, playgrounds and parks."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Penalties for being caught in possession of drugs are severe."]},{"k":"hs","s":["Using cameras in secure areas"]},{"k":"p","s":["Do not take photographs near government or military establishments."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Although same-sex relationships are not illegal, public attitudes are less tolerant than in the UK and showing affection in public may receive negative attention. There’s no provision under Ukrainian legislation guaranteeing freedom from discrimination on the grounds of sexual orientation. Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Surrogacy"]},{"k":"p","s":["Due to the security challenges across all of Ukraine, we must currently advise against commissioning any surrogacy arrangements there. Further information about surrogacy overseas can be found ",["here.","https://www.gov.uk/government/publications/surrogacy-overseas/surrogacy-overseas"]]},{"k":"p","s":["Commissioning a surrogacy will not automatically mean that the child holds British citizenship. If you want to bring your child born through surrogacy from Ukraine to the UK, you must ",["apply for a full British passport","https://www.gov.uk/overseas-passports"],"."]},{"k":"p","s":["The FCDO cannot facilitate your departure from Ukraine."]},{"k":"p","s":["If you are considering changing your surrogacy arrangements, or making a new arrangement with a Ukrainian woman in another country, check surrogacy advice for that country also."]},{"k":"h","s":["Transport information and risks"]},{"k":"p","s":["Due to the Russian invasion of Ukraine, expect disruption to travel and transport networks. Only travel if you judge it is safe to do so. We cannot confirm which services are operating. Where possible, check before travelling."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Unregulated taxi drivers can overcharge. Use official taxis, which have the name and telephone number of the taxi company on the side of the door and on the top of the taxi."]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Ukraine, see information on ",["driving abroad","https://www.gov.uk/driving-abroad"]," and read the ",["RAC’s Ukraine guide","https://www.rac.co.uk/drive/travel/country/ukraine/"],"."]},{"k":"p","s":["You must have a ",["1968 international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well as your UK driving licence to drive in Ukraine. The 1949 IDP is not accepted any more. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["You need to carry a green card to drive in Ukraine. A ",["green card","https://www.gov.uk/vehicle-insurance/driving-abroad"]," is proof that you have vehicle insurance when driving abroad."]},{"k":"p","s":["You must carry original vehicle registration papers, ownership documents and insurance papers at all times. You must show them when crossing borders and if you are stopped by the police. This also applies to rental vehicles. If you do not have these papers when stopped by the police they have the right to impound your vehicle and charge you for this."]},{"k":"hs","s":["Car hire"]},{"k":"p","s":["If you intend to rent a vehicle for your travel in Ukraine, check with the car hire company and insurance company about their policy on renting cars in Ukraine and any other country you will pass through, especially non-EU countries. Ensure they provide you with a rental agreement permitting you to cross the Ukrainian border."]},{"k":"hs","s":["Driving standards"]},{"k":"p","s":["Roads are of variable quality and routes may be affected by the ongoing invasion. Avoid night-time travel wherever possible."]},{"k":"p","s":["Local driving standards are poor. Street lights are weak and road users often ignore speed limits, traffic lights and road signs. Drivers frequently make turns and change lane without indicating. There are a high number of traffic accidents, including fatalities. Speeding, drink driving and infrequent use of helmets, seat belts and child restraints in vehicles are the main contributing factors."]},{"k":"p","s":["If you have a road accident, you must wait for the police to assess the accident. Call the police on 102. Local officials generally only speak Ukrainian and Russian."]},{"k":"hs","s":["Driving regulations"]},{"k":"p","s":["It is illegal to drive with any alcohol content in your blood."]},{"k":"p","s":["Police can stop vehicles and give fines for minor offences such as illegal parking or jumping a red light. They may carry a credit card terminal to collect payment on the spot, or fines can be paid online or at a bank within 15 days. See payment options (in Ukrainian). The police officer should give their name and rank, explain why you have been stopped and make an administrative offence report. The police may film interactions with members of the public."]},{"k":"hs","s":["Leaving Ukraine by car"]},{"k":"p","s":["You can leave Ukraine by car through most border crossing points, but Ukraine’s border crossings with Russia and Belarus are closed to regular traffic."]},{"k":"p","s":["There could be long queues at the border crossing points with EU member states and Moldova. Have a good supply of food, water, warm clothing, medication and fuel."]},{"k":"p","s":["The State Border Guard Service of Ukraine (SBGSU) website has a ",["map showing the border crossing locations","https://dpsu.gov.ua/en/map"],". The State Customs Service lists ",["waiting times at border crossing points","https://kordon.live/index_en.html"],"."]},{"k":"p","s":["At the border crossing, the SBGSU will check:"]},{"k":"li","s":["car registration documents"]},{"k":"li","s":["the insurance documents for the vehicle (green card)"]},{"k":"p","s":["For more information see the ",["SBGSU website","https://dpsu.gov.ua/en/informaciya-dlya-inozemciv-ta-osib-bez-gromadyanstva"]," or call the SBGSU hotline on 1598 from a Ukrainian mobile."]},{"k":"p","s":["If you leave the country in a vehicle registered in the UK, which you temporarily imported to Ukraine, you will have to provide your import customs declaration when leaving."]},{"k":"p","s":["You may need additional documents. For further information on leaving Ukraine by car, contact the ",["State Customs Service of Ukraine","https://customs.gov.ua/en/contacts"]," (site in Ukrainian)."]},{"k":"hs","s":["Rail travel"]},{"k":"p","s":["If you travel by train, make sure your belongings are secure. Do not agree to look after the luggage of a fellow traveller or allow it to be stored in your compartment."]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["Ukraine’s air space is closed."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Floods can cause travel disruption and damage to property and infrastructure. ",["Check weather warnings from Ukraine’s Hydrometeorological Center","https://www.meteo.gov.ua/en/Meteorolohichni-poperedzhennya"]," before travel and follow the advice of the local authorities."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Ukraine. It only covers regions where FCDO has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/ukraine/warnings-and-insurance"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/ukraine/safety-and-security"],"."]},{"k":"h","s":["Crimea and eastern Ukraine"]},{"k":"p","s":["FCDO advises against all travel to all regions in eastern Ukraine, including any Ukrainian territories which are temporarily under Russian control. FCDO is not able to provide in-person assistance to anyone in these regions."]},{"k":"h","s":["Border with Belarus"]},{"k":"p","s":["FCDO advises against all travel to within 50km of the border with Belarus in the regions of:"]},{"k":"li","s":["Volyn"]},{"k":"li","s":["Rivne"]},{"k":"li","s":["Zhytomyr"]},{"k":"p","s":["This is due to the ongoing presence of Russian and Belarusian military and security personnel on the Belarusian side of the border."]},{"k":"h","s":["All other regions of Ukraine"]},{"k":"p","s":["FCDO advises against all travel to all other regions of Ukraine except for specific regions of western Ukraine (see below). This includes any areas temporarily under Russian control such as Zaporizhzhia and Kherson regions."]},{"k":"h","s":["Western regions"]},{"k":"p","s":["FCDO advises against all but essential travel to the regions of:"]},{"k":"li","s":["Zakarpattia"]},{"k":"li","s":["Ivano-Frankivsk"]},{"k":"li","s":["Ternopil"]},{"k":"li","s":["Chernivtsi"]},{"k":"li","s":["Lviv"]},{"k":"li","s":["Volyn"]},{"k":"li","s":["Rivne"]},{"k":"li","s":["Zhytomyr"]},{"k":"p","s":["In the event of attacks, follow the advice of the local authorities, including responding to air raid sirens."]},{"k":"hs","s":["To enter or exit Crimea"]},{"k":"p","s":["In theory foreign nationals need to provide their passport and a special permit issued by the territorial body of the ",["State Migration Service of Ukraine","https://dmsu.gov.ua/en-home.html"],". However, due to the ongoing war in Ukraine, it is not currently possible for foreign nationals to enter or exit Crimea."]},{"k":"p","s":["The Crimean sea ports of Kerch, Sevastopol, Feodosia, Yalta and Yevpatoria have been designated by the Ukrainian authorities as closed to international shipping."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 103 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Ukraine","https://travelhealthpro.org.uk/country/232/ukraine#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"hs","s":["Pharmacies"]},{"k":"p","s":["Due to the ongoing invasion, some supply chains are interrupted, and some medical products are hard to come by. Information on which pharmacies are operational is provided by local authorities and pharmacy networks."]},{"k":"p","s":["The Ukrainian Ministry of Health operates a hotline at +380 (0)800 60 20 19 to coordinate access to insulin and other critical medicines for those who need it. The service Tabletki.ua (site in Ukrainian) is continuing to operate and tries to maintain hourly updates about availability of medicines nationwide."]},{"k":"p","s":["Pharmacies may close without notice. Maintain a stock of essential medication. Pharmacies in smaller towns may not have the same variety of medications available in the bigger cities. Pharmacies are usually easily identifiable by the presence of a green cross or the word ‘apteka’ (аптека). Some stronger medications require a prescription from a doctor, written in Ukrainian."]},{"k":"h","s":["Healthcare in Ukraine"]},{"k":"p","s":["FCDO has a list of ",["healthcare providers in Ukraine","https://www.gov.uk/government/publications/list-of-medical-facilities-in-kyiv"],". Due to the ongoing invasion, we cannot confirm that all these providers are operating."]},{"k":"p","s":["State medical facilities in Ukraine are generally poor. Private clinics and hospitals offer a better standard of care, though these do not always meet western standards and practices. If you require emergency medical treatment, it is likely that you will be taken to a state hospital unless you can show that you have comprehensive medical insurance cover."]},{"k":"p","s":["English is not widely spoken and you may face communication difficulties if you do not speak Ukrainian."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Ukraine"]},{"k":"p","s":["Ambulance: 103"]},{"k":"p","s":["Fire: 101"]},{"k":"p","s":["Police: 102"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Ukraine"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Ukraine"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Ukraine"]," in Ukraine"]},{"k":"li","s":["dealing with a ",["death in Ukraine","https://www.gov.uk/government/publications/ukraine-bereavement-guide"]]},{"k":"li","s":["being ",["arrested or imprisoned in Ukraine","https://www.gov.uk/government/publications/ukraine-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis,","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"]," such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/ukraine/british-consulate-kyiv"]," including in an emergency."]},{"k":"p","s":["Or in an emergency you can call our 24-hour helpline and select the option for ‘consular services for British nationals’:"]},{"k":"li","s":["For a domestic call from Ukraine, call +380 (0)44 490 3660"]},{"k":"li","s":["For an international call to the UK call +44 (0)20 7008 5000"]},{"k":"p","s":["The British Embassy in Kyiv is unable to provide in-person assistance."]},{"k":"p","s":["Full consular services are available at British embassies in neighbouring countries."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/ukraine/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":31278,"change":"Updated information about the Russian invasion of Ukraine ('Warnings and insurance' page)."}};
